/**
 * @summary Challenge a friend to a game
 */
export const createChallengeBodyMaxPlayersMin = 2;
export const createChallengeBodyMaxPlayersMax = 4;

export const createChallengeBodyVictoryRequirementDefault = 20;

export const CreateChallengeBody = zod.object({
  eventFrequency: zod
    .enum(["off", "standard", "frequent"])
    .optional()
    .describe(
      "Regular game Event frequency; Standard selects one unique Event per tier, Frequent selects two, and Off selects none. New games use a separate countdown-driven Event deck. Omitted settings default to Standard.",
    ),
  challengedUsername: zod.string(),
  maxPlayers: zod
    .number()
    .min(createChallengeBodyMaxPlayersMin)
    .max(createChallengeBodyMaxPlayersMax)
    .optional(),
  victoryRequirement: zod
    .union([zod.literal(15), zod.literal(20), zod.literal(25)])
    .default(createChallengeBodyVictoryRequirementDefault)
    .describe(
      "Eminence required to trigger the final round; 20 is standard and 15 is the shorter custom format",
    ),
  cinematicMode: zod
    .enum(["standard", "epic"])
    .optional()
    .describe("Luminary cinematic presentation mode"),
  turnTimerSeconds: zod.number().nullish(),
});

